                totalScore: total,
                avgScore: Math.round(avg),
                overallScore: Math.round(avg),
                roundsPassed: passed,
                totalPeriods: history.length,
                stars: stars,
                title: title,
                performance: title,
                insights: insights
            };
        }

        getPresets() { return null; }

        _updateStarsDisplay(state) {
            var el = document.getElementById(`starsDisplay`);
            if (!el) return;
            var s = state.domainState.starLevel || 0;
            el.textContent = s + ` / 3`;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];

            var t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var tagEl = document.getElementById(`roundTag`);
            if (tagEl) tagEl.textContent = t(round.tag);

            var titleEl = document.getElementById(`roundTitle`);
            if (titleEl) titleEl.textContent = t(round.title);

            var briefEl = document.getElementById(`roundBrief`);
            if (briefEl) briefEl.textContent = t(round.brief);

            var teachEl = document.getElementById(`roundTeaches`);
            if (teachEl) teachEl.textContent = t(round.teaches);

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (!panel) continue;
                if (i === idx) {
                    panel.classList.add(`is-active`);
                    panel.style.display = `block`;
                } else {
                    panel.classList.remove(`is-active`);
                    panel.style.display = `none`;
                }
            }
        }

        _updateDiagram(state) {
            var el = document.getElementById(`orgDiagram`);
            if (!el) return;
            var layers = state.domainState.lastLayers || 3;
            var span = state.domainState.lastSpan || 6;
            var struct = state.domainState.lastStructure || `functional`;
            if (layers < 1) layers = 1;
            if (layers > 5) layers = 5;

            var html = ``;
            for (var L = 0; L < layers; L++) {
                var count = 1;
                if (L === 0) count = 1;
                else if (L === 1) count = Math.min(span, 6);
                else count = Math.min(span + 1, 8);

                html += `<div class="orgchart-sim-diagram-layer">`;
                for (var n = 0; n < count; n++) {
                    var cls = L === 0 ? `is-top` : (L === 1 ? `is-mid` : ``);
                    html += `<div class="orgchart-sim-diagram-node ` + cls + `">` + (L === 0 ? `CEO` : (L === 1 ? `M` : `•`)) + `</div>`;
                }
                html += `</div>`;
                if (L < layers - 1) html += `<div class="orgchart-sim-diagram-connector"></div>`;
            }
            var t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
            html += `<div class="orgchart-sim-diagram-caption">` + t(`diagram_caption`)
                 + `: ` + layers + ` ` + t(`layers_word`) + ` · ` + t(`span_word`) + ` ` + span
                 + ` · ` + t(`struct_` + struct) + `</div>`;
            el.innerHTML = html;
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
            var s = summary || {};
            var stars = s.stars || 1;
            var score = (typeof s.overallScore === `number`) ? s.overallScore
                      : (typeof s.avgScore === `number` ? s.avgScore : 0);
            var starRow = ``;
            for (var i = 0; i < 3; i++) { starRow += (i < stars ? `★` : `☆`); }
            var tierKey = stars === 3 ? `perf_coo` : (stars === 2 ? `perf_designer` : `perf_manager`);
            var rounds = this.ROUNDS.length;
            var insightsHtml = ``;
            if (s.insights && s.insights.length) {
                insightsHtml = `<ul class="orgchart-sim-complete-insights">`;
                s.insights.forEach(function(ins) { insightsHtml += `<li>` + ins + `</li>`; });
                insightsHtml += `</ul>`;
            }
            var kpi = function(val, label) {
                return `<div class="orgchart-sim-complete-kpi"><span class="oscc-val">` + val + `</span><span class="oscc-lbl">` + label + `</span></div>`;
            };
            var html = `` +
                `<div class="orgchart-sim-complete">` +
                    `<div class="orgchart-sim-complete-stars">` + starRow + `</div>` +
                    `<div class="orgchart-sim-complete-title">` + t(`complete_title`) + `</div>` +
                    `<div class="orgchart-sim-complete-score">` + score + `<span class="osc-max">/100</span></div>` +
                    `<div class="orgchart-sim-complete-tier">` + t(tierKey) + `</div>` +
                    `<div class="orgchart-sim-complete-kpis">` +
                        kpi((s.avgScore || 0), t(`cm_avg`)) +
                        kpi((s.roundsPassed || 0) + `/` + rounds, t(`cm_passed`)) +
                        kpi((s.totalScore || 0), t(`cm_total`)) +
                    `</div>` +
                    (insightsHtml ? (`<div class="orgchart-sim-complete-insights-wrap"><div class="osci-head">` + t(`cm_insights`) + `</div>` + insightsHtml + `</div>`) : ``) +
                `</div>`;
            return html;
        }

